import React,{useState,useMemo,useRef,useCallback,useEffect} from 'react';
import {compareDocuments} from './core.js';
import {extractFile} from './extract.js';
import {bytes} from './offline.js';
import {savedReview} from './storage.js';
import {targetFor} from './navigation.js';
import {exportWorkspace} from './workspaceExports.js';
import DocumentPane from './DocumentPane.jsx';
import Icon from './icons.jsx';
import {useWorkspaceLayout,Splitter,ZoomInput} from './WorkspaceControls.jsx';
import {t,label,sampleLabels} from './i18n.js';

function Modal({title,onClose,children,lang}){const root=useRef();useEffect(()=>{const previous=document.activeElement;root.current.querySelector('button,input,select')?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const els=[...root.current.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus();};},[]);return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)onClose();}}><section ref={root} className="modal" role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="icon-button" aria-label={t(lang,'close')} onClick={onClose}><Icon name="close"/></button></header>{children}</section></div>;}

function ChangeSidebar({result,selection,select,reviews,updateReview,query,setQuery,filter,setFilter,topic,setTopic,lang}){
 const visible=useMemo(()=>result?.rows.filter(r=>{const q=query.trim().toLocaleLowerCase(),matches=!q||[r.old?.text,r.new?.text,label(lang,r.title),reviews[r.id]?.note].join(' ').toLocaleLowerCase().includes(q);return matches&&(filter==='all'||filter==='changes'&&r.kind!=='unchanged'||filter==='high'&&r.priority==='High'||filter==='unreviewed'&&r.kind!=='unchanged'&&!reviews[r.id]?.reviewed||filter===r.kind)&&(topic==='all'||r.categories.includes(topic));})||[],[result,reviews,query,filter,topic,lang]);
 const state=reviews[selection?.id]||{},index=selection?result.changes.findIndex(r=>r.id===selection.id):-1;
 return <aside className="change-sidebar"><div className="sidebar-top"><div className="sidebar-title"><h2>{t(lang,'changes')}</h2><span className="count-badge">{result?.changes.length||0}</span><div className="change-arrows"><button className="icon-button" aria-label={t(lang,'prev')} disabled={!result?.changes.length} onClick={()=>select(result.changes[(index-1+result.changes.length)%result.changes.length])}><Icon name="chevron" style={{transform:'rotate(180deg)'}}/></button><button className="icon-button" aria-label={t(lang,'next')} disabled={!result?.changes.length} onClick={()=>select(result.changes[(index+1)%result.changes.length])}><Icon name="chevron"/></button></div></div><div className="search-field"><Icon name="search"/><input aria-label={t(lang,'search')} placeholder={t(lang,'search')} value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filters"><select aria-label="Filter changes" value={filter} onChange={e=>setFilter(e.target.value)}>{[['changes','all'],['high','high'],['unreviewed','pending'],['all','full']].map(([v,k])=><option key={v} value={v}>{t(lang,k)}</option>)}{['modified','deleted','added','moved','unchanged'].map(v=><option key={v} value={v}>{label(lang,v)}</option>)}</select><select aria-label="Filter topic" value={topic} onChange={e=>setTopic(e.target.value)}><option value="all">{t(lang,'topics')}</option>{['Payment','Amounts','Dates / deadlines','Penalties','Liability','Termination','Other'].map(v=><option key={v} value={v}>{label(lang,v)}</option>)}</select></div></div>
 <nav className="change-list" aria-label={t(lang,'changes')}>{visible.length?visible.map(row=><button key={row.id} className={`change-item ${selection?.id===row.id?'selected':''}`} data-change-id={row.id} data-kind={row.kind} aria-current={selection?.id===row.id?'true':undefined} onClick={()=>select(row)}><span className={`change-bar ${row.kind}`}/><div className="item-main"><div><strong>{label(lang,row.title)}</strong><span className={`priority ${row.priority}`}>{label(lang,row.priority)}</span></div>{row.kind==='modified'?<p><span className="old-value">{row.values.before.slice(0,30)||'∅'}</span><span className="arrow">→</span><span className="new-value">{row.values.after.slice(0,30)||'∅'}</span></p>:<p className="item-heading">{row.old?.heading||row.new?.heading}</p>}<small>{row.old?.location||row.new?.location}{reviews[row.id]?.reviewed&&<Icon name="check"/>}</small></div></button>):<div className="no-results">{result?(result.changes.length?t(lang,'noResults'):t(lang,'unchanged')):t(lang,'noSelection')}{result&&<button className="text-button" onClick={()=>{setQuery('');setFilter('all');setTopic('all');}}>{t(lang,'reset')}</button>}</div>}</nav>
 <section className="review-inspector">{selection?<><div className="inspector-title"><span className={`change-bar ${selection.kind}`}/><h3>{label(lang,selection.title)}</h3></div><div className="evidence"><label>{t(lang,'before')}</label><p className="old-evidence" title={selection.values.before}>{selection.values.before||'—'}</p><label>{t(lang,'after')}</label><p className="new-evidence" title={selection.values.after}>{selection.values.after||'—'}</p></div>{selection.kind!=='unchanged'&&<><button className={`review-button ${state.reviewed?'is-reviewed':'primary'}`} onClick={()=>updateReview(selection.id,{reviewed:!state.reviewed})}><Icon name="check"/>{t(lang,state.reviewed?'reviewed':'review')}</button><label className="note-label" htmlFor="review-note">{t(lang,'note')}</label><textarea id="review-note" value={state.note||''} placeholder={t(lang,'notePlaceholder')} maxLength={4000} onChange={e=>updateReview(selection.id,{note:e.target.value})}/></>}</>:<p className="muted">{t(lang,'noSelection')}</p>}<div className="device-note"><Icon name="lock"/>{t(lang,'local')}</div></section></aside>;
}

export default function App(){
 const [lang,setLang]=useState(()=>{try{return localStorage.getItem('contractdiff-language')==='zh'?'zh':'en';}catch{return'en';}}),[files,setFiles]=useState([null,null]),[docs,setDocs]=useState(null),[result,setResult]=useState(null),[reviews,setReviews]=useState({}),[selectedId,setSelectedId]=useState(null),[busy,setBusy]=useState(false),[status,setStatus]=useState(''),[error,setError]=useState(''),[modal,setModal]=useState(null),[sample,setSample]=useState('en-pdf'),[forceOCR,setForceOCR]=useState(false),[query,setQuery]=useState(''),[filter,setFilter]=useState('changes'),[topic,setTopic]=useState('all'),[zoom,setZoom]=useState(1),[sync,setSync]=useState(true),[dirty,setDirty]=useState(false),[exportMode,setExportMode]=useState('summary'),[mobileTab,setMobileTab]=useState('old');
 const panes=useRef({}),pending=useRef(null),lock=useRef(null),unlock=useRef(),frame=useRef(),resultRef=useRef(result),selectionRef=useRef(null);resultRef.current=result;
 const preserveView=useCallback(()=>{Object.values(panes.current).forEach(p=>p?.remember());},[]);
 const workspace=useWorkspaceLayout(preserveView);
 const rowMaps=useMemo(()=>({old:new Map(result?.rows.filter(r=>r.old).map(r=>[r.old.id,r])||[]),new:new Map(result?.rows.filter(r=>r.new).map(r=>[r.new.id,r])||[])}),[result]);
 const rowMapsRef=useRef(rowMaps);rowMapsRef.current=rowMaps;
 const selection=result?.rows.find(r=>r.id===selectedId)||null;selectionRef.current=selection;
 const reviewed=result?.changes.filter(r=>reviews[r.id]?.reviewed).length||0;
 const lockScroll=value=>{lock.current=value;clearTimeout(unlock.current);unlock.current=setTimeout(()=>{lock.current=null;},180);};
 const tryJump=useCallback(side=>{const job=pending.current;if(!job)return;const r=resultRef.current?.rows.find(r=>r.id===job.id);if(!r)return;const target=targetFor(r,side,resultRef.current.rows);if(target.block&&panes.current[side]?.goTo(target.block.id,0,.22,false,true)){job[side]=false;lockScroll('both');}},[]);
 const select=useCallback(row=>{setSelectedId(row.id);pending.current={id:row.id,old:true,new:true};lockScroll('both');requestAnimationFrame(()=>{tryJump('old');tryJump('new');});},[]);
 const register=useCallback((side,api)=>{panes.current[side]=api;},[]);
 const onScroll=useCallback(side=>{pending.current=null;if(!sync)return;cancelAnimationFrame(frame.current);frame.current=requestAnimationFrame(()=>{const from=panes.current[side],toSide=side==='old'?'new':'old',to=panes.current[toSide],anchor=from?.anchor();if(!anchor||!to)return;const r=rowMapsRef.current[side].get(anchor.blockId);if(!r)return;const target=targetFor(r,toSide,resultRef.current.rows);if(target.block)to.goTo(target.block.id,target.missing?0:anchor.ratio);});},[sync]);
 useEffect(()=>()=>{cancelAnimationFrame(frame.current);clearTimeout(unlock.current);},[]);
 useEffect(()=>{document.documentElement.lang=lang==='zh'?'zh-CN':'en';try{localStorage.setItem('contractdiff-language',lang);}catch{}},[lang]);
 const resetUI=res=>{setQuery('');setFilter('changes');setTopic('all');setReviews({});setSelectedId(res.changes[0]?.id||null);pending.current=res.changes[0]?{id:res.changes[0].id,old:true,new:true}:null;setDirty(false);};
 const run=async chosen=>{setBusy(true);setError('');setStatus(t(lang,'processing'));setModal(null);setDocs(null);setResult(null);pending.current=null;try{const ds=[];for(const f of chosen)ds.push(await extractFile(f,setStatus,forceOCR));const res=compareDocuments(...ds);resultRef.current=res;setDocs(ds);setResult(res);resetUI(res);setStatus(res.changes.length?`${t(lang,'done')} · ${res.changes.length} ${t(lang,'count')}`:t(lang,'unchanged'));}catch(e){setError(e.message);}finally{setBusy(false);}};
 const loadSample=async()=>{const pair=window.ContractDiffSamples[sample].map(v=>new File([bytes(v.data)],v.name));setFiles(pair);await run(pair);};
 const updateReview=(id,patch)=>{setReviews(prev=>({...prev,[id]:{...prev[id],...patch}}));setDirty(true);};
 const storage=async mode=>{setError('');try{if(mode==='save'){await savedReview('save',{version:2,docs,result,reviews});setStatus(t(lang,'saved'));setDirty(false);}else if(mode==='load'){const v=await savedReview('load');if(!v)throw new Error(t(lang,'noSaved'));setDocs(v.docs);setResult(v.result);resultRef.current=v.result;resetUI(v.result);setReviews(v.reviews);setFiles(v.docs.map(d=>new File([d.raw],d.name)));setModal(null);setStatus(t(lang,'loaded'));}else{await savedReview('clear');setStatus(t(lang,'deleted'));}}catch(e){setError(e.message);}};
 const changeZoom=value=>{preserveView();if(selection)pending.current={id:selection.id,old:true,new:true};lockScroll('both');setZoom(Math.max(.5,Math.min(3,Math.round(value*100)/100)));};
 const exportAction=async format=>{setBusy(true);setError('');setStatus(t(lang,'exporting'));try{await exportWorkspace({mode:exportMode,format,result,docs,reviews,lang,progress:setStatus});setStatus(format==='pdf'?t(lang,'printHint'):t(lang,'export')+' ✓');setModal(null);}catch(e){setError(e.message);}finally{setBusy(false);}};
 const noticeCount=docs?.reduce((n,d)=>n+d.warnings.length,0)||0;
 return <div className={`app-shell ${workspace.reading?'reading-mode':''} ${workspace.hidden?'sidebar-hidden':''} ${workspace.dragging?'resizing':''}`}><header className="global-toolbar"><div className="brand"><div className="brand-icon"><Icon name="file"/></div><h1>ContractDiff</h1><span className="brand-divider"/><span className="brand-subtitle">{t(lang,'workspace')}</span></div><div className="global-actions"><button className="sidebar-toggle" aria-label={t(lang,workspace.hidden?'showSidebar':'hideSidebar')} aria-expanded={!workspace.hidden} onClick={workspace.toggleSidebar}><Icon name="sidebar"/><span>{t(lang,'sidebar')}</span></button><button onClick={()=>setModal('open')} disabled={busy}><Icon name="open"/>{t(lang,'open')}</button><button disabled={!result||busy} onClick={()=>storage('save')}><Icon name="save"/>{t(lang,'save')}{dirty&&<i className="dirty-dot" aria-hidden="true" title={t(lang,'unsaved')}/>}</button><button className="primary" disabled={!result||busy} onClick={()=>setModal('export')}><Icon name="export"/>{t(lang,'export')}</button><button className="language-button" aria-label="Switch language / 切换语言" onClick={()=>setLang(lang==='en'?'zh':'en')}><span className={lang==='en'?'active':''}>EN</span><span>/</span><span className={lang==='zh'?'active':''}>中文</span></button></div></header>
 <div className="workspace-toolbar"><div className="document-title"><strong title={docs?.[0].blocks[0]?.text}>{docs?.[0].blocks[0]?.text.slice(0,65)||t(lang,'overview')}</strong><span className="toolbar-divider"/><span className="count-badge" data-testid="change-count">{result?.changes.length||0} {t(lang,'count')}</span><span className="review-count">{reviewed} {t(lang,'of')} {result?.changes.length||0} {t(lang,'reviewCount')}</span></div><div className="view-controls">{workspace.reading&&<div className="reading-navigation"><button className="icon-button" aria-label={t(lang,'prev')} disabled={!result?.changes.length} onClick={()=>{const i=result.changes.findIndex(r=>r.id===selectedId);select(result.changes[(i-1+result.changes.length)%result.changes.length]);}}><Icon name="chevron" style={{transform:'rotate(180deg)'}}/></button><span>{result?.changes.length?result.changes.findIndex(r=>r.id===selectedId)+1:0} / {result?.changes.length||0}</span><button className="icon-button" aria-label={t(lang,'next')} disabled={!result?.changes.length} onClick={()=>{const i=result.changes.findIndex(r=>r.id===selectedId);select(result.changes[(i+1)%result.changes.length]);}}><Icon name="chevron"/></button></div>}<label className="sync-control">{t(lang,'sync')}<input type="checkbox" checked={sync} onChange={e=>setSync(e.target.checked)} aria-label={t(lang,'sync')}/><span className="switch"/></label><span className="toolbar-divider"/><button className="zoom-button" aria-label={t(lang,'zoomOut')} disabled={!docs||zoom<=.5} onClick={()=>changeZoom(zoom-.15)}>−</button><ZoomInput zoom={zoom} onChange={changeZoom} disabled={!docs} lang={lang}/><button className="zoom-button" aria-label={t(lang,'zoomIn')} disabled={!docs||zoom>=3} onClick={()=>changeZoom(zoom+.15)}>+</button><button disabled={!docs} onClick={()=>changeZoom(1)}>{t(lang,'fit')}</button><span className="toolbar-divider"/><button className={`reading-button ${workspace.reading?'active':''}`} aria-pressed={workspace.reading} title={workspace.reading?t(lang,'readingHint'):t(lang,'reading')} disabled={!docs} onClick={()=>{if(!workspace.reading)setMobileTab('old');workspace.toggleReading();}}><Icon name="reading"/>{t(lang,workspace.reading?'exitReading':'reading')}</button></div></div>
 {error&&<div className="error-banner" role="alert">{error}<button aria-label={t(lang,'close')} onClick={()=>setError('')}>×</button></div>}
 <div className="mobile-tabs">{['changes','old','new'].map(v=><button className={mobileTab===v?'selected':''} key={v} onClick={()=>{setMobileTab(v);if(selection){pending.current={id:selection.id,old:true,new:true};requestAnimationFrame(()=>{tryJump(v);});}}}>{t(lang,v==='old'?'original':v==='new'?'revised':'changes')}</button>)}</div>
 <main ref={workspace.root} className={`review-workspace mobile-${mobileTab}`} style={{'--sidebar-width':workspace.layout.sidebar+'px','--left-size':workspace.layout.split+'fr','--right-size':(1-workspace.layout.split)+'fr'}}><ChangeSidebar result={result} selection={selection} select={select} reviews={reviews} updateReview={updateReview} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} topic={topic} setTopic={setTopic} lang={lang}/><Splitter kind="sidebar" workspace={workspace} lang={lang}/>{docs&&result?['old','new'].map((side,i)=><React.Fragment key={side+docs[i].hash}>{i===1&&<Splitter kind="documents" workspace={workspace} lang={lang}/>}<DocumentPane doc={docs[i]} side={side} result={result} selection={selection} zoom={zoom} lang={lang} register={register} onScroll={onScroll} onSelect={select} onReady={tryJump}/></React.Fragment>):<section className="empty-workspace"><div className="empty-document-icon"><Icon name="file" width="36" height="36"/></div><h2>{busy?t(lang,'processing'):t(lang,'empty')}</h2><p>{busy?t(lang,'busyHint'):t(lang,'emptyBody')}</p>{busy?<div className="progress-line"><i/></div>:<><button className="primary" onClick={()=>setModal('open')}><Icon name="open"/>{t(lang,'open')}</button><div className="sample-inline"><select aria-label={t(lang,'sampleType')} value={sample} onChange={e=>setSample(e.target.value)}>{Object.entries(sampleLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button onClick={loadSample}>{t(lang,'sample')}</button></div><small>{t(lang,'sampleHint')}</small></>}</section>}</main>
 <footer className="statusbar"><span><Icon name="lock"/>{t(lang,'privacy')}</span><span className="status-legal"><Icon name="info"/>{t(lang,'legal')}</span><p role="status" aria-live="polite">{status||t(lang,'ready')}</p>{noticeCount>0&&<button className="notice-button" onClick={()=>setModal('notices')}>{t(lang,'notices')} · {noticeCount}</button>}</footer>
 {modal==='open'&&<Modal title={t(lang,'open')} lang={lang} onClose={()=>!busy&&setModal(null)}><div className="upload-fields">{['original','revised'].map((side,i)=><label className="file-field" key={side}><strong>{t(lang,side)}</strong><span><Icon name="file"/>{files[i]?.name||t(lang,'choose')}</span><input type="file" aria-label={lang==='en'?(i?'Revised contract':'Original contract'):t(lang,side)} accept=".pdf,.docx" disabled={busy} onChange={e=>{const f=e.target.files[0];if(f)setFiles(prev=>prev.map((old,j)=>j===i?f:old));e.target.value='';}}/></label>)}</div><label className="check-label"><input type="checkbox" checked={forceOCR} onChange={e=>setForceOCR(e.target.checked)}/>{t(lang,'force')}</label><p className="field-hint">{t(lang,'forceHint')}</p><button className="primary wide" disabled={busy||files.some(f=>!f)} onClick={()=>run(files)}>{t(lang,'compare')}</button><div className="sample-options"><label>{t(lang,'sampleType')}</label><div><select aria-label={t(lang,'sampleType')} value={sample} onChange={e=>setSample(e.target.value)}>{Object.entries(sampleLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button disabled={busy} onClick={loadSample}>{t(lang,'sample')}</button></div></div><div className="local-storage"><p><Icon name="lock"/>{t(lang,'saveHint')}</p><button disabled={busy} onClick={()=>storage('load')}>{t(lang,'load')}</button><button className="text-button danger" disabled={busy} onClick={()=>storage('clear')}>{t(lang,'clear')}</button></div></Modal>}
 {modal==='export'&&<Modal title={t(lang,'export')} lang={lang} onClose={()=>!busy&&setModal(null)}><p className="modal-description">{result.changes.length} {t(lang,'count')} · {reviewed} {t(lang,'reviewCount')}</p><div className="export-options">{[['summary','summary','summaryHelp'],['full','comparison','fullHelp']].map(([v,k,help])=><label className={exportMode===v?'selected':''} key={v}><input type="radio" name="export-mode" value={v} checked={exportMode===v} onChange={()=>setExportMode(v)}/><span><strong>{t(lang,k)}</strong><small>{t(lang,help)}</small></span></label>)}</div><details className="more-exports"><summary>{t(lang,'moreExports')}</summary><label><input type="radio" name="export-mode" value="legacy" checked={exportMode==='legacy'} onChange={()=>setExportMode('legacy')}/>{t(lang,'fullText')}</label></details><div className="export-actions"><button disabled={busy} onClick={()=>exportAction('html')}>{t(lang,'html')}</button><button className="primary" disabled={busy} onClick={()=>exportAction('pdf')}>{t(lang,'pdf')}</button></div><p className="export-privacy"><Icon name="lock"/>{t(lang,'exportPrivacy')}</p>{busy&&<p className="field-hint" role="status">{status}</p>}</Modal>}
 {modal==='notices'&&<Modal title={t(lang,'extraction')} lang={lang} onClose={()=>setModal(null)}>{docs.map(d=><div className="notice-document" key={d.name}><h3>{d.name}</h3><ul>{d.warnings.map((w,i)=><li key={i}>{w}</li>)}</ul></div>)}<p className="field-hint">{t(lang,'legal')}</p></Modal>}
 </div>;
}


