export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function htmlReport(result,docs,reviews){
 const text=(parts,kind)=>parts.map(p=>p.changed?`<mark class="${kind}">${escape(p.text)}</mark>`:escape(p.text)).join('');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>ContractDiff comparison report</title><style>body{font:15px/1.6 Arial,"Microsoft YaHei",sans-serif;color:#18243b;max-width:1100px;margin:40px auto;padding:0 24px}h1{font-size:28px}h2{font-size:19px}a{color:#007f78}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{border:1px solid #cbd3df;padding:15px;vertical-align:top;overflow-wrap:anywhere;white-space:pre-wrap;text-align:left}mark{padding:1px 0}.del{background:#ffdada}.add{background:#d6f4dc}article{margin:24px 0;break-inside:avoid}.meta{color:#526176;font-size:12px}.warn{background:#fff5d6;padding:12px}.High{color:#9c2b28}.Medium{color:#97600e}@media print{body{margin:0;padding:0;font-size:10pt}button{display:none}a{color:inherit;text-decoration:none}thead{display:table-header-group}article{break-inside:auto}tr{break-inside:avoid}h2,h2+p{break-after:avoid}@page{margin:15mm}</style></head><body><h1>ContractDiff comparison report</h1><p>${escape(docs[0].name)} → ${escape(docs[1].name)}</p><p class="meta">Generated ${escape(result.created)} · ${result.changes.length} changed blocks · All blocks included; search filters do not restrict this report.</p><p>Automated priorities identify topics for human review. They are not legal conclusions. Extracted text may omit layout, images or content that could not be read.</p>${docs.map(d=>`<p class="meta">${escape(d.name)} · SHA-256: ${escape(d.hash||'sample')}<br>${d.warnings.map(escape).join('<br>')}</p>`).join('')}<h2>Important changes</h2><ol>${result.changes.map(r=>`<li><a href="#${r.id}">${escape(r.title)}</a> · <span class="${r.priority}">${r.priority}</span> · ${escape(r.old?.location||r.new?.location)} · ${reviews[r.id]?.reviewed?'Reviewed':'Unreviewed'}</li>`).join('')||'<li>No extracted-text changes detected.</li>'}</ol>${result.rows.map(r=>`<article id="${r.id}"><h2>${escape(r.old?.heading||r.new?.heading||r.title)}</h2><p class="meta">${escape(r.title)} · ${r.priority}${r.moved?' · Relative order changed':''}${r.confidence!==null&&r.confidence<1?' · Similarity-matched; verify alignment':''}</p><table><thead><tr><th>Original · ${escape(r.old?.location||'No original text')}</th><th>Revised · ${escape(r.new?.location||'No revised text')}</th></tr></thead><tbody><tr><td>${r.old?text(r.diff.old,'del'):'[Added in revised version]'}</td><td>${r.new?text(r.diff.neo,'add'):'[Deleted from revised version]'}</td></tr></tbody></table><p class="meta">Review: ${reviews[r.id]?.reviewed?'Reviewed':'Unreviewed'}${reviews[r.id]?.note?' · '+escape(reviews[r.id].note):''}</p></article>`).join('')}<p>Source locators refer to the imported documents. PDF page geometry and DOCX pagination are not reproduced in this extracted-text report.</p></body></html>`;
}
export function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function exportHTML(result,docs,reviews){download(htmlReport(result,docs,reviews),'ContractDiff-report.html','text/html');}
export function exportPDF(result,docs,reviews){const w=window.open('','_blank');if(!w)throw new Error('Allow pop-ups for this local file to open the print report.');w.document.write(htmlReport(result,docs,reviews));w.document.close();w.focus();setTimeout(()=>w.print(),400);}

