import {htmlReport,escape,download} from './report.js';
import {openPDF} from './extract.js';
import {renderPDFPage,renderDOCX,markDOCXForExport} from './rendering.js';
import {label,t} from './i18n.js';

export function conciseReport(result,docs,reviews,lang='en'){
 let html=htmlReport({...result,rows:result.changes},docs,reviews).replaceAll('ContractDiff comparison report',`ContractDiff · ${t(lang,'summary')}`).replace('All blocks included; search filters do not restrict this report.',lang==='zh'?'仅包含变更；包含全部审阅备注。':'Changed blocks only; includes all review notes regardless of filters.');
 if(lang==='zh')html=html.replace('<html lang="en">','<html lang="zh-CN">').replaceAll('Important changes','重要变更').replaceAll('Original ·','原始版本 ·').replaceAll('Revised ·','修订版本 ·').replaceAll('Unreviewed','未审阅').replaceAll('Reviewed','已审阅').replaceAll('Review:','审阅：');return html;
}
async function documentHTML(doc,side,result,progress){
 const root=document.createElement('div');root.className='export-render-root';Object.assign(root.style,{position:'fixed',left:'-20000px',top:'0',width:'816px',background:'white'});document.body.append(root);let handle;
 try{if(doc.format==='docx'){await renderDOCX(doc,root,side);markDOCXForExport(root,result.rows,side);root.querySelectorAll('[data-block]').forEach(e=>e.id=`${side}-${e.dataset.block}`);return `<div class="export-docx">${root.innerHTML}</div>`;}
 handle=await openPDF(doc.raw.slice(0));const pages=[];for(let n=1;n<=handle.pdf.numPages;n++){progress(`${doc.name} · ${n}/${handle.pdf.numPages}`);const host=document.createElement('div');host.className='pdf-paper';host.style.position='relative';root.replaceChildren(host);const blocks=doc.blocks.filter(b=>b.page===n);const {canvas}=await renderPDFPage(handle.pdf,n,host,1.4,blocks,result.rows,side);const width=parseFloat(host.style.width),height=parseFloat(host.style.height);const image=document.createElement('img');image.src=canvas.toDataURL('image/png');image.alt=`${doc.name} · page ${n}`;image.style.width='100%';image.style.display='block';canvas.replaceWith(image);host.querySelector('.textLayer')?.remove();host.querySelectorAll('.source-anchor,.change-hit').forEach(e=>{e.removeAttribute('role');e.removeAttribute('tabindex');for(const[k,size]of [['left',width],['width',width],['top',height],['height',height]])e.style[k]=100*parseFloat(e.style[k])/size+'%';if(e.dataset.block)e.id=`${side}-${e.dataset.block}`;});host.style.width='100%';host.style.height='auto';host.style.setProperty('--page-ratio',width/height);pages.push(`<section class="export-pdf-page">${host.outerHTML}<small>${n} / ${handle.pdf.numPages}</small></section>`);}
 return pages.join('');
 }finally{await handle?.close();root.remove();}
}
export async function fullComparison(result,docs,reviews,lang='en',progress=()=>{}){
 const sources=[];for(let i=0;i<2;i++)sources.push(await documentHTML(docs[i],i?'new':'old',result,progress));
 const bothPDF=docs.every(d=>d.format==='pdf');
 const documentHeading=i=>`<h2 class="document-name">${t(lang,i?'revised':'original')} · ${escape(docs[i].name)}</h2>`;
 let sourceHTML;if(bothPDF){const pages=sources.map(html=>{const temp=document.createElement('template');temp.innerHTML=html;return [...temp.content.children].map(e=>e.outerHTML);});sourceHTML=Array.from({length:Math.max(...pages.map(p=>p.length))},(_,n)=>`<section class="pdf-pair">${pages.map((list,i)=>`<div class="full-document">${documentHeading(i)}${list[n]||`<p class="meta">${lang==='zh'?'此版本无此页。':'No page at this position in this version.'}</p>`}</div>`).join('')}</section>`).join('');}else sourceHTML=sources.map((html,i)=>`<section class="full-document">${documentHeading(i)}${html}</section>`).join('');
 const summary=result.changes.map(r=>`<li><strong>${escape(label(lang,r.title))}</strong> · ${escape(label(lang,r.priority))} · ${reviews[r.id]?.reviewed?t(lang,'reviewed'):t(lang,'pending')}<br>${r.old?`<a href="#old-${r.old.id}">${escape(r.old.location)}</a>`:escape(t(lang,'missing'))} ↔ ${r.new?`<a href="#new-${r.new.id}">${escape(r.new.location)}</a>`:escape(t(lang,'missing'))}${r.kind==='modified'?`<br><del>${escape(r.values.before)}</del> → <ins>${escape(r.values.after)}</ins>`:''}${reviews[r.id]?.note?`<p>${escape(reviews[r.id].note)}</p>`:''}</li>`).join('');
 return `<!doctype html><html lang="${lang==='zh'?'zh-CN':'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="connect-src 'none'; object-src 'none'; img-src data:; font-src data:; base-uri 'none'"><title>ContractDiff · ${t(lang,'comparison')}</title><style>body{margin:30px;font:14px/1.5 system-ui,'Microsoft YaHei',sans-serif;color:#1d1d1f;background:#f5f5f7}h1{font-size:26px}a{color:#0066cc}li{margin:14px 0}li p{white-space:pre-wrap}header,.index{background:white;border:1px solid #ddd;border-radius:10px;padding:24px;margin-bottom:20px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.full-document{min-width:0}.pdf-comparison{display:block}.pdf-pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start}.document-name{font-size:16px}.document-name{overflow-wrap:anywhere}.export-pdf-page{background:white;border:1px solid #ddd;margin-bottom:18px;break-inside:avoid}.export-pdf-page small{display:block;text-align:center}.pdf-paper{position:relative}.source-anchor{position:absolute;pointer-events:none}.source-anchor:target{outline:3px solid #007aff;background:#007aff12;scroll-margin-top:30px}.change-hit{position:absolute;background:#ff6b6b55}.change-hit.new{background:#46be7055}.change-hit.moved{background:#6e9eec44}.export-docx{background:white;overflow-wrap:break-word}.export-docx>div:has(>.docx-body){width:100%}.docx-body>[class$="-wrapper"]{padding:0;background:white}.docx-body section{max-width:100%;box-sizing:border-box;box-shadow:none!important}.docx-body [data-block]:target{outline:2px solid #007aff}.del,del{background:#ffdada}.add,ins{background:#d8f4df}mark{color:inherit}.meta{color:#666;font-size:12px}.mapping-fallback{padding:20px;border:1px dashed #999}.docx-body a{color:inherit;text-decoration:none}@media print{@page{size:A3 landscape;margin:12mm}body{margin:0;background:white;font-size:10pt}header,.index{break-inside:avoid}a{color:inherit}.export-pdf-page{break-inside:avoid}.columns{gap:8mm}.pdf-pair{display:flex;gap:8mm;break-before:page;break-inside:avoid}.pdf-pair>.full-document{width:calc(50% - 4mm)}.document-name{font-size:10pt;line-height:1.2;margin:0 0 3mm}.pdf-paper{width:min(100%,calc(235mm * var(--page-ratio)))!important;margin:auto}.export-pdf-page{margin:0;border:0}.export-docx{zoom:.82}.docx-body table,.docx-body tr{break-inside:avoid}.docx-body h1,.docx-body h2,.docx-body h3{break-after:avoid}}@media(max-width:800px){body{margin:12px}.columns,.pdf-pair{grid-template-columns:1fr}}</style></head><body><header><h1>ContractDiff · ${t(lang,'comparison')}</h1><p>${escape(docs[0].name)} → ${escape(docs[1].name)}</p><p>${t(lang,'legal')}</p><p class="meta">${lang==='zh'?'保留每份合同的原始顺序。PDF 显示原始页面；DOCX 为格式预览，分页可能不同。':'Each document retains its own source order. PDF pages retain their layout; DOCX is a formatted preview with potentially different pagination.'}</p>${docs.map(d=>`<p class="meta">${escape(d.name)} · SHA-256 ${escape(d.hash)}<br>${d.warnings.map(escape).join('<br>')}</p>`).join('')}</header><section class="index"><h2>${t(lang,'changes')} · ${result.changes.length}</h2><ol>${summary||`<li>${t(lang,'unchanged')}</li>`}</ol></section><div class="columns${bothPDF?' pdf-comparison':''}">${sourceHTML}</div></body></html>`;
}
export async function exportWorkspace({mode,format,result,docs,reviews,lang,progress}){
 // Open synchronously to preserve the user gesture for browser popup policies.
 const printWindow=format==='pdf'?window.open('','_blank'):null;if(format==='pdf'&&!printWindow)throw new Error(lang==='zh'?'请允许此本地应用打开弹出窗口。':'Allow popups for this local app to print the report.');
 if(printWindow){printWindow.document.body.textContent=t(lang,'exporting');printWindow.document.title='ContractDiff';}
 try{const html=mode==='full'?await fullComparison(result,docs,reviews,lang,progress):mode==='legacy'?htmlReport(result,docs,reviews):conciseReport(result,docs,reviews,lang);
 if(format==='html')download(html,`ContractDiff-${mode==='full'?'full-comparison':mode==='legacy'?'text-comparison':'change-report'}.html`,'text/html');
 else {printWindow.document.open();printWindow.document.write(html);printWindow.document.close();await printWindow.document.fonts.ready;await Promise.all([...printWindow.document.images].map(img=>img.decode().catch(()=>{})));printWindow.focus();printWindow.print();}
 }catch(e){printWindow?.close();throw e;}
}
