function db(){return new Promise((resolve,reject)=>{const q=indexedDB.open('contractdiff-private-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('review');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export async function savedReview(mode,value){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('review',mode==='load'?'readonly':'readwrite'),s=tx.objectStore('review');const q=mode==='load'?s.get('current'):mode==='clear'?s.delete('current'):s.put(value,'current');tx.oncomplete=()=>{resolve(q.result);d.close();};tx.onerror=()=>{reject(tx.error);d.close();};});}
